using System;
using System.Linq;
using System.Collections.Generic;
using Prometheus;
class SlipTests0256 {
 static int count;static void Check(bool value,string name){if(!value)throw new Exception("FAIL "+name);count++;Console.WriteLine("PASS "+name);}
 static Clip Clip(string asset,string stream,string track,string name,double source){return new Clip{id=Store.Id(),asset_id=asset,stream_id=stream,track_id=track,name=name,timeline_start=Rational.Frame(1),duration=Rational.Frame(4),source_in=Rational.Time(source),speed=new Rational(1,1)};}
 static void Main(){var e=new Editor();string vt=e.Project.Active.tracks.First(t=>t.kind=="video").id,at=e.Project.Active.tracks.First(t=>t.kind=="audio").id,asset=Store.Id(),video=Store.Id(),audio=Store.Id();e.Commit(p=>{p.assets.Add(new Asset{id=asset,name="linked",locator=new Locator{path="fixture.mp4"},sha256=new string('a',64),presentation_origin=Rational.Time(0),streams=new List<StreamInfo>{new StreamInfo{id=video,ordinal=0,kind="video",codec="h264",pts_origin=Rational.Time(0),time_base=new Rational(1,60),duration=Rational.Time(10),nominal_fps=new Rational(60,1)},new StreamInfo{id=audio,ordinal=1,kind="audio",codec="aac",pts_origin=Rational.Time(0),time_base=new Rational(1,48000),duration=Rational.Time(8),sample_rate=48000,channels=2}}});p.Active.clips.Add(Clip(asset,video,vt,"video",2));p.Active.clips.Add(Clip(asset,audio,at,"audio",2.25));p.Active.link_groups.Add(new LinkGroup{id=Store.Id(),clip_ids=p.Active.clips.Select(c=>c.id).ToList()});});string anchor=e.Project.Active.clips.First(c=>c.track_id==vt).id;e.Slip(anchor,3);var vc=e.Project.Active.clips.First(c=>c.track_id==vt);var ac=e.Project.Active.clips.First(c=>c.track_id==at);Check(Math.Abs(vc.source_in.Seconds-3)<0.0001&&Math.Abs(ac.source_in.Seconds-3.25)<0.0001,"linked audio and video keep their source offset");Check(vc.timeline_start.Seconds==1&&ac.timeline_start.Seconds==1&&vc.duration.Seconds==4&&ac.duration.Seconds==4,"Slip keeps timeline position and clip duration");Check(Math.Abs(e.SlipSource(anchor,6)-3.75)<0.0001,"preview clamps to the shortest linked source handle");e.Slip(anchor,6);vc=e.Project.Active.clips.First(c=>c.track_id==vt);ac=e.Project.Active.clips.First(c=>c.track_id==at);Check(Math.Abs(vc.source_in.Seconds-3.75)<0.0001&&Math.Abs(ac.source_in.Seconds-4)<0.0001,"commit uses the same clamped source position as preview");e.Slip(anchor,-3);vc=e.Project.Active.clips.First(c=>c.track_id==vt);ac=e.Project.Active.clips.First(c=>c.track_id==at);Check(Math.Abs(vc.source_in.Seconds)<0.0001&&Math.Abs(ac.source_in.Seconds-0.25)<0.0001,"negative drag stops at source start without breaking links");e.Undo();Check(Math.Abs(e.Project.Active.clips.First(c=>c.track_id==vt).source_in.Seconds-3.75)<0.0001,"Slip undoes as one edit");Store.Validate(e.Project);e.Undo();e.Undo();e.Commit(p=>{p.Active.clips.First(c=>c.track_id==vt).speed=new Rational(2,1);foreach(var clip in p.Active.clips)clip.duration=Rational.Frame(3);});e.Slip(anchor,3);vc=e.Project.Active.clips.First(c=>c.track_id==vt);ac=e.Project.Active.clips.First(c=>c.track_id==at);Check(Math.Abs(vc.source_in.Seconds-3)<0.0001&&Math.Abs(ac.source_in.Seconds-2.75)<0.0001,"linked sources with different speeds move by the same timeline duration");Store.Validate(e.Project);Console.WriteLine("PASS "+count+" Slip engine checks");}
}
